import { Component, Emit, Vue } from 'vue-property-decorator';
import { fbShare, whatsapp, tw } from 'vanilla-sharing';
import { OverlaysEventEmitter } from '../../event-emitter';
import { SocialMediaSite } from '../../types';

@Component({
    name: 'SocialShare'
})
export default class SocialShare extends Vue {
    public isVisible: boolean = false;
    public url: string = '';
    public title: string = '';
    public image: string = '';

    public created() {
        this.show = this.show.bind(this);
    }

    public mounted() {
        OverlaysEventEmitter.on('showSocialShare', this.show);
    }

    public beforeDestroy() {
        OverlaysEventEmitter.off('showSocialShare', this.show);
    }

    public show(title: string, url: string, image: string) {
        this.title = title;
        this.url = url;
        this.image = image;
        this.isVisible = true;
    }

    @Emit('onShare')
    public onShare(type: SocialMediaSite) {
        switch (type) {
            case 'Twitter':
                tw({
                    url: this.url,
                    title: this.title,
                    hashtags: ['tombola', 'winner', 'jointhefun'],
                });
                break;
            case 'WhatsApp':
                whatsapp({
                    url: this.url,
                    title: this.title,
                });
                break;
            case 'Facebook':
                fbShare({
                    url: this.url,
                    redirectUri: this.url,
                    fbAppId: '1670520089968094',
                    quote: this.title
                });
                break;
        }
        this.hide();
        return type;
    }

    @Emit('onClose')
    public onClose() {
        this.hide();
    }

    private hide() {
        this.isVisible = false;
    }
}
